// WP25 A-invariant 24 — de ingebouwde beelden van `photoFormats.selfTest`.
//
// Synthetisch, zonder persoonsgegevens: 64×48, blauw met een rood vlak
// linksboven. De JPEG komt van sharp (q60, zonder EXIF); de HEIC is dezelfde
// JPEG via `sips -s format heic` (de encoder van Apple). Bytes in de code,
// niet in storage: de controle leest en schrijft niets op de deployment.

const JPEG_BASE64 =
  "";

const HEIC_BASE64 =
  "";

function decode(base64: string): Uint8Array {
  const bin = atob(base64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const selfTestJpeg = (): Uint8Array => decode(JPEG_BASE64);
export const selfTestHeic = (): Uint8Array => decode(HEIC_BASE64);
